import pytest
from fastapi.testclient import TestClient
from sqlalchemy.orm import Session
import uuid

@pytest.fixture
def mock_published_form(test_db: Session):
    # Helper to insert a published form
    return str(uuid.uuid4())

@pytest.fixture
def mock_draft_form(test_db: Session):
    # Helper to insert a draft form
    return str(uuid.uuid4())

class TestLeadCollectionAPI:
    """[P0] API Integration tests for Lead Collection (Area 9)"""

    def test_anonymous_user_can_submit_to_published_form(self, client: TestClient, mock_published_form):
        """
        [P0] Should accept public submissions to a published form and flag as production lead.
        """
        payload = {
            "data": {
                "first_name": "John",
                "last_name": "Doe",
                "email": "john.doe@example.com"
            }
        }

        response = client.post(
            f"/api/forms/{mock_published_form}/submissions",
            json=payload
        )

        assert response.status_code == 201
        data = response.json()
        assert data["success"] is True
        assert data["data"]["is_preview"] is False # Crucial verification

    def test_authenticated_user_can_submit_preview_lead(self, client: TestClient, auth_headers, mock_draft_form):
        """
        [P0] Should accept submissions to a draft form IF user is authenticated, and flag as preview lead.
        """
        payload = {
            "data": {
                "email": "preview.tester@example.com"
            },
            "is_preview_test": True
        }

        response = client.post(
            f"/api/forms/{mock_draft_form}/submissions",
            headers=auth_headers,
            json=payload
        )

        assert response.status_code == 201
        data = response.json()
        assert data["data"]["is_preview"] is True

    def test_anonymous_user_cannot_submit_to_draft_form(self, client: TestClient, mock_draft_form):
        """
        [P0] Should reject public submissions to an unpublished/draft form.
        """
        payload = {
            "data": {
                "email": "hacker@example.com"
            }
        }

        response = client.post(
            f"/api/forms/{mock_draft_form}/submissions",
            json=payload
        )

        assert response.status_code in [403, 404, 401] # Depending on if we 404 the route entirely or 403
